// ── Release signing (review C5) ────────────────────────────────────────────────────────────────
// The upload key is supplied by the operator at build time and is NEVER committed. Two sources are
// supported, env vars taking precedence (CI) over the gitignored keystore.properties file (local):
//   keystore.properties (gitignored):  storeFile, storePassword, keyAlias, keyPassword
//   environment variables:             BEAMFALL_KEYSTORE_PATH, BEAMFALL_KEYSTORE_PASSWORD,
//                                      BEAMFALL_KEY_ALIAS, BEAMFALL_KEY_PASSWORD
// When no credentials are present (CI smoke builds, contributors), the release signingConfig is
// simply not created and `release` builds stay unsigned — the build still succeeds.
val keystoreProps =
    Properties().apply {
        val f = rootProject.file("keystore.properties")
        if (f.exists()) f.inputStream().use { load(it) }
    }

fun signingValue(
    propKey: String,
    envKey: String,
): String? =
    (System.getenv(envKey)?.takeIf { it.isNotBlank() } ?: keystoreProps.getProperty(propKey))
        ?.takeIf { it.isNotBlank() }

val keystorePath = signingValue("storeFile", "BEAMFALL_KEYSTORE_PATH")
val keystorePassword = signingValue("storePassword", "BEAMFALL_KEYSTORE_PASSWORD")
val keyAliasValue = signingValue("keyAlias", "BEAMFALL_KEY_ALIAS")
val keyPasswordValue = signingValue("keyPassword", "BEAMFALL_KEY_PASSWORD")
val hasReleaseSigning =
    keystorePath != null && keystorePassword != null && keyAliasValue != null && keyPasswordValue != null

android {
    namespace = "com.beamfall.mobile"
    compileSdk = 36

    defaultConfig {
        applicationId = "com.beamfall.mobile"
        minSdk = 29
        targetSdk = 36
        // ANDROID-RELEASE-VERSION-SOURCE-1: read from the root project's single authoritative
        // source (gradle/version.properties + git commit-history depth) rather than restating a
        // literal here — see build.gradle.kts.
        versionCode = rootProject.extra["releaseVersionCode"] as Int
        versionName = rootProject.extra["releaseVersionName"] as String
        buildConfigField("String", "RELEASE_COMMIT_SHA", "\"${rootProject.extra["releaseCommitSha"]}\"")
        // AUDIT-ANDROID-9: required for the app-mobile androidTest source set (instrumented smoke
        // test) so `:app-mobile:connectedDebugAndroidTest` actually runs code instead of no-oping.
        testInstrumentationRunner = "androidx.test.runner.AndroidJUnitRunner"
    }

    buildFeatures {
        buildConfig = true
        compose = true
    }

    signingConfigs {
        if (hasReleaseSigning) {
            create("release") {
                storeFile = rootProject.file(keystorePath!!)
                storePassword = keystorePassword
                keyAlias = keyAliasValue
                keyPassword = keyPasswordValue
            }
        }
    }
    // UI-state screenshot catalog runs as JVM unit tests via Robolectric (no device). Robolectric
    // needs merged Android resources + the manifest to inflate Compose; default-return keeps any
    // unstubbed framework call deterministic instead of throwing. See ui-catalog/README.md.
    testOptions {
        unitTests.isIncludeAndroidResources = true
        unitTests.isReturnDefaultValues = true
    }

    buildTypes {
        debug {
            isPseudoLocalesEnabled = true
        }
        release {
            // Use the operator-supplied upload key when present; otherwise leave unsigned so CI and
            // contributor builds don't break (an unsigned release artifact is not Play-uploadable).
            signingConfig = if (hasReleaseSigning) signingConfigs.getByName("release") else null
            isMinifyEnabled = true
            isShrinkResources = true
            proguardFiles(
                getDefaultProguardFile("proguard-android-optimize.txt"),
                "proguard-rules.pro",
            )
        }
        create("benchmark") {
            initWith(getByName("release"))
            signingConfig = signingConfigs.getByName("debug")
            isDebuggable = false
            matchingFallbacks += listOf("release")
        }
    }
}

